const fs = require("node:fs/promises");
const path = require("node:path");

async function guardarInforme(ruta, contenido) {
  await fs.mkdir(path.dirname(ruta), { recursive: true });
  await fs.writeFile(ruta, contenido, "utf8");
  return fs.readFile(ruta, "utf8");
}

async function leerInforme(ruta) {
  try {
    return await fs.readFile(ruta, "utf8");
  } catch (error) {
    if (error.code === "ENOENT") return null;
    throw error;
  }
}

module.exports = { guardarInforme, leerInforme };

